CREATE TABLE iview_dataset (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_id BIGINT NOT NULL,
    dataset_name VARCHAR(100) NOT NULL,
    query_sql CLOB NOT NULL,
    description VARCHAR(500) NOT NULL DEFAULT '',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_iview_dataset_source FOREIGN KEY (source_id) REFERENCES iview_data_source(id) ON DELETE RESTRICT,
    CONSTRAINT uq_iview_dataset_source_name UNIQUE (source_id, dataset_name)
);
